import pytest

DEFAULTS: dict[str, str] = {"mode": "fast", "level": "3"}


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the defaults mode=fast and level=3.

    keys[i] is set to values[i]. Returns the resulting values ordered as:
    mode, level, then every other key's value in order of first appearance
    in keys. If a key repeats, its last value wins and its position is that
    of its first appearance. Raises ValueError if len(keys) != len(values).
    Pure: performs no I/O and does not mutate its arguments.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    merged: dict[str, str] = dict(DEFAULTS)
    for key, value in zip(keys, values, strict=True):
        merged[key] = value
    return list(merged.values())


def test_no_settings_returns_defaults() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode_only() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level_only() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_in_any_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_follow_in_given_order() -> None:
    assert settings(["z", "a", "m"], ["1", "2", "3"]) == ["fast", "3", "1", "2", "3"]


def test_extras_mixed_with_overrides() -> None:
    result = settings(["color", "level", "debug", "mode"], ["red", "7", "on", "slow"])
    assert result == ["slow", "7", "red", "on"]


def test_duplicate_key_last_value_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_duplicate_extra_keeps_first_position() -> None:
    result = settings(["x", "y", "x"], ["1", "2", "3"])
    assert result == ["fast", "3", "3", "2"]


def test_empty_string_values_are_kept() -> None:
    assert settings(["mode", "x"], ["", ""]) == ["", "3", ""]


def test_keys_are_case_sensitive() -> None:
    assert settings(["Mode"], ["slow"]) == ["fast", "3", "slow"]


def test_inputs_not_mutated() -> None:
    keys = ["a", "mode"]
    values = ["1", "slow"]
    settings(keys, values)
    assert keys == ["a", "mode"]
    assert values == ["1", "slow"]


def test_defaults_not_mutated() -> None:
    settings(["mode", "extra"], ["slow", "x"])
    assert DEFAULTS == {"mode": "fast", "level": "3"}
    assert settings([], []) == ["fast", "3"]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings([], ["1"])

